"""Generated tests for converted code (Round 7).

The converters' own checks stop at "does it parse". These tests go one step further, aimed at the failures seen when the
converters were fed files they had never seen: a name used but never defined (an import the conversion removed), a
Terraform variable referenced but never declared, AWS resources left behind, tables that disappear from SQL.

Each test says where it ran:
  "here"    - run by the tool, statically, on the generated files (nothing is executed or deployed);
  "not run" - generated for the engineer to run in an environment that has the data (for example a parity query that
              needs both Redshift and BigQuery).
For every conversion a test file is also generated that repeats the checks, so the engineer can keep it in their repo.
"""
from __future__ import annotations

import ast
import builtins
import re
from typing import Any

PY_AWS = ("boto3", "botocore", "awsglue", "aws_lambda_powertools")


# --------------------------------------------------------------------------- python
def _bound_and_loaded(tree: ast.AST) -> tuple[set[str], list[tuple[str, int]]]:
    """Over-approximates every name bound anywhere in the module (so scoping mistakes are not reported as false
    positives) and lists every name read."""
    bound, loaded = set(dir(builtins)) | {"__file__", "__name__", "__doc__", "__spec__", "__builtins__"}, []
    for n in ast.walk(tree):
        if isinstance(n, ast.Name):
            (bound.add(n.id) if isinstance(n.ctx, (ast.Store, ast.Del)) else loaded.append((n.id, n.lineno)))
        elif isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
            bound.add(n.name)
        elif isinstance(n, ast.arg):
            bound.add(n.arg)
        elif isinstance(n, (ast.Import, ast.ImportFrom)):
            for a in n.names:
                bound.add((a.asname or a.name).split(".")[0])
        elif isinstance(n, ast.ExceptHandler) and n.name:
            bound.add(n.name)
        elif isinstance(n, (ast.Global, ast.Nonlocal)):
            bound.update(n.names)
        elif isinstance(n, ast.MatchAs) and n.name:
            bound.add(n.name)
    return bound, loaded


def undefined_names(src: str) -> list[tuple[str, int]]:
    bound, loaded = _bound_and_loaded(ast.parse(src))
    seen, out = set(), []
    for name, line in loaded:
        if name not in bound and name not in seen:
            seen.add(name)
            out.append((name, line))
    return out


def aws_imports(src: str) -> list[str]:
    out = []
    for n in ast.walk(ast.parse(src)):
        if isinstance(n, ast.Import):
            out += [a.name for a in n.names if a.name.split(".")[0] in PY_AWS]
        elif isinstance(n, ast.ImportFrom) and n.module and n.module.split(".")[0] in PY_AWS:
            out.append(n.module)
    return out


def top_defs(src: str) -> set[str]:
    try:
        return {n.name for n in ast.parse(src).body if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef))}
    except SyntaxError:
        return set()


def local_imports(src: str) -> set[str]:
    out = set()
    for n in ast.walk(ast.parse(src)):
        if isinstance(n, ast.ImportFrom) and n.module and n.level == 0:
            out.add(n.module.split(".")[0])
        elif isinstance(n, ast.Import):
            out.update(a.name.split(".")[0] for a in n.names)
    return out


# --------------------------------------------------------------------------- terraform
def tf_var_refs(text: str) -> set[str]:
    return set(re.findall(r"\bvar\.([A-Za-z_][A-Za-z0-9_-]*)", text))


def tf_declared(text: str) -> set[str]:
    return set(re.findall(r'^\s*variable\s+"([^"]+)"', text, re.M))


def tf_aws_resources(text: str) -> list[str]:
    return re.findall(r'^\s*(?:resource|data)\s+"(aws_[A-Za-z0-9_]+)"', text, re.M)


# --------------------------------------------------------------------------- sql
def sql_tables(text: str, dialect: str) -> set[str]:
    try:
        import sqlglot
        from sqlglot import exp
        out = set()
        for stmt in sqlglot.parse(text, read=dialect):
            if stmt is None:
                continue
            for t in stmt.find_all(exp.Table):
                if t.name:
                    out.add(t.name.lower())
        return out
    except Exception:  # noqa: BLE001  a parse failure is reported by the converter's own check
        return set()


def parity_sql(source_sql: str) -> str:
    tables = sorted(sql_tables(source_sql, "redshift"))
    lines = ["-- Parity checks generated by the Migration Accelerator. NOT RUN: run each pair in Redshift and in BigQuery",
             "-- after loading, and compare the results. Matching counts are evidence, not proof that every row is equal.", ""]
    if not tables:
        lines.append("-- No tables were found in the source SQL, so no parity query was generated.")
    for t in tables:
        lines += [f"-- {t}", f"-- Redshift:", f"SELECT COUNT(*) AS row_count FROM {t};",
                  f"-- BigQuery (replace the dataset name):", f"SELECT COUNT(*) AS row_count FROM `your_dataset.{t}`;", ""]
    return "\n".join(lines)


# --------------------------------------------------------------------------- runner
def _r(name: str, status: str, detail: str, ran: str = "here") -> dict:
    return {"name": name, "status": status, "detail": detail, "ran": ran}


def run_tests(conv: dict) -> tuple[list[dict], dict[str, str]]:
    """Returns (results, generated test files). conv is a conversion as stored in ctx: file_type, outputs, source_text."""
    ft, outs, src = conv.get("file_type"), conv.get("outputs") or {}, conv.get("source_text") or ""
    results, files = [], {}
    stem = re.sub(r"\W+", "_", (conv.get("source_file") or "conversion").rsplit(".", 1)[0]).strip("_").lower()
    py_outs = {k: v for k, v in outs.items() if k.endswith(".py")}
    tf_outs = {k: v for k, v in outs.items() if k.endswith(".tf")}
    sql_outs = {k: v for k, v in outs.items() if k.endswith(".sql")}

    if py_outs:
        siblings = {k.rsplit("/", 1)[-1][:-3] for k in py_outs}
        for k, v in py_outs.items():
            try:
                und = undefined_names(v)
            except SyntaxError as e:
                results.append(_r(f"{k}: compiles", "FAIL", f"syntax error line {e.lineno}: {e.msg}"))
                continue
            results.append(_r(f"{k}: every name used is defined", "FAIL" if und else "PASS",
                              ("not defined anywhere: " + ", ".join(f"{n} (line {ln})" for n, ln in und[:8])) if und
                              else "no undefined names found"))
            aws = aws_imports(v)
            results.append(_r(f"{k}: no AWS SDK imports", "FAIL" if aws else "PASS", ", ".join(aws) or "none left"))
            missing_mod = sorted(m for m in local_imports(v) if m.startswith("gcp_") and m not in siblings)
            if missing_mod:
                results.append(_r(f"{k}: local modules present", "FAIL", f"imports {', '.join(missing_mod)} but no such file was generated"))
        if src and ft in ("python", "lambda_python", "glue_pyspark", "airflow_dag"):
            gone = sorted(top_defs(src) - set().union(*(top_defs(v) for v in py_outs.values())))
            results.append(_r("functions kept from the source", "REVIEW" if gone else "PASS",
                              ("not found in the output: " + ", ".join(gone) + " (renamed or dropped; check callers)") if gone
                              else "every top-level function of the source is defined in the output"))
        files[f"tests/test_{stem}_generated.py"] = _py_test_file(py_outs)

    if tf_outs:
        all_tf = "\n".join(tf_outs.values())
        und = sorted(tf_var_refs(all_tf) - tf_declared(all_tf))
        results.append(_r("terraform: every var.* is declared", "FAIL" if und else "PASS",
                          ("referenced but not declared: " + ", ".join(und) + " (terraform validate would fail)") if und else "all declared"))
        aws = tf_aws_resources(all_tf)
        results.append(_r("terraform: no AWS resources left", "FAIL" if aws else "PASS", ", ".join(sorted(set(aws))) or "none"))
        results.append(_r("terraform validate / plan in a GCP project", "NOT_RUN",
                          "needs Terraform and GCP credentials; run the generated test or `terraform validate`", "not run"))
        files[f"tests/test_{stem}_terraform.py"] = _tf_test_file(tf_outs)

    if sql_outs and src:
        before, after = sql_tables(src, "redshift"), set().union(*(sql_tables(v, "bigquery") for v in sql_outs.values()))
        lost = sorted(before - after)
        results.append(_r("sql: every source table still referenced", "REVIEW" if lost else "PASS",
                          ("not found in the output: " + ", ".join(lost)) if lost else f"{len(before)} table(s) carried over"))
        files[f"tests/parity_{stem}.sql"] = parity_sql(src)
        results.append(_r("sql: row-count parity between Redshift and BigQuery", "NOT_RUN",
                          f"generated tests/parity_{stem}.sql; needs both warehouses", "not run"))
    if not results:
        results.append(_r("no generated test applies to this output type", "NOT_RUN", f"{ft}: covered by the converter's own checks", "not run"))
    return results, files


def _py_test_file(py_outs: dict[str, str]) -> str:
    paths = sorted(py_outs)
    return f'''"""Generated by the Migration Accelerator. Static checks only: nothing is imported, executed or deployed.
Run with: pytest {'{this file}'}  (from the folder that contains the generated output)."""
import ast
import builtins
from pathlib import Path

FILES = {paths!r}
AWS = {PY_AWS!r}


def _names(tree):
    bound, loaded = set(dir(builtins)) | {{"__file__", "__name__"}}, []
    for n in ast.walk(tree):
        if isinstance(n, ast.Name):
            (bound.add(n.id) if isinstance(n.ctx, (ast.Store, ast.Del)) else loaded.append(n.id))
        elif isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
            bound.add(n.name)
        elif isinstance(n, ast.arg):
            bound.add(n.arg)
        elif isinstance(n, (ast.Import, ast.ImportFrom)):
            bound.update((a.asname or a.name).split(".")[0] for a in n.names)
        elif isinstance(n, ast.ExceptHandler) and n.name:
            bound.add(n.name)
    return bound, loaded


def test_compiles_and_names_defined():
    for f in FILES:
        tree = ast.parse(Path(f).read_text())
        bound, loaded = _names(tree)
        assert not sorted(set(loaded) - bound), f"{{f}}: undefined {{sorted(set(loaded) - bound)}}"


def test_no_aws_sdk_imports():
    for f in FILES:
        for n in ast.walk(ast.parse(Path(f).read_text())):
            mods = [a.name for a in n.names] if isinstance(n, ast.Import) else [n.module or ""] if isinstance(n, ast.ImportFrom) else []
            assert not [m for m in mods if m.split(".")[0] in AWS], f"{{f}} still imports {{mods}}"
'''


def _tf_test_file(tf_outs: dict[str, str]) -> str:
    paths = sorted(tf_outs)
    return f'''"""Generated by the Migration Accelerator. Static checks on the generated Terraform; run `terraform validate`
and `terraform plan` against a non-production GCP project as the real test."""
import re
from pathlib import Path

FILES = {paths!r}


def _all():
    return "\\n".join(Path(f).read_text() for f in FILES)


def test_every_variable_declared():
    t = _all()
    used = set(re.findall(r"\\bvar\\.([A-Za-z_][A-Za-z0-9_-]*)", t))
    declared = set(re.findall(r'^\\s*variable\\s+"([^"]+)"', t, re.M))
    assert used <= declared, f"undeclared: {{sorted(used - declared)}}"


def test_no_aws_resources_left():
    assert not re.findall(r'^\\s*(?:resource|data)\\s+"aws_', _all(), re.M)
'''


def summary(results: list[dict]) -> dict[str, Any]:
    from collections import Counter
    c = Counter(r["status"] for r in results)
    return {k: c.get(k, 0) for k in ("PASS", "FAIL", "REVIEW", "NOT_RUN")}
